'use strict';
const ZeroTools=(()=>{
  let findBar=null,hits=[],index=-1,query='';
  function clearMarks(){document.querySelectorAll('mark.zero-find').forEach(mark=>mark.replaceWith(document.createTextNode(mark.textContent)));document.querySelectorAll('.browse-content,.reader-text').forEach(el=>el.normalize());hits=[];index=-1}
  function mark(){clearMarks();if(!query)return updateCount();const root=ZeroReader.isOpen()?document.querySelector('.reader-text'):document.querySelector('.browse-content');if(!root)return updateCount();const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:node=>node.parentElement.closest('button,input,textarea,select,script,style,mark')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let nodes=[],node;while(node=walker.nextNode())nodes.push(node);for(const node of nodes){const text=node.nodeValue,lower=text.toLocaleLowerCase(),needle=query.toLocaleLowerCase();let start=0,at=lower.indexOf(needle);if(at<0)continue;const fragment=document.createDocumentFragment();while(at>=0){fragment.append(document.createTextNode(text.slice(start,at)));const mark=document.createElement('mark');mark.className='zero-find';mark.textContent=text.slice(at,at+query.length);fragment.append(mark);hits.push(mark);start=at+query.length;at=lower.indexOf(needle,start)}fragment.append(document.createTextNode(text.slice(start)));node.replaceWith(fragment)}if(hits.length)move(1);else updateCount()}
  function updateCount(){if(findBar)findBar.querySelector('.find-count').textContent=hits.length?`${index+1}/${hits.length}`:'0/0'}
  function move(offset){if(!hits.length)return updateCount();hits[index]?.classList.remove('current');index=(index+offset+hits.length)%hits.length;hits[index].classList.add('current');hits[index].scrollIntoView({block:'center',behavior:'smooth'});updateCount()}
  function closeFind(){clearMarks();findBar?.remove();findBar=null}
  function find(){closeFind();findBar=document.createElement('div');findBar.className='zero-find-bar';findBar.innerHTML=`<input placeholder="${t('查找文字','Find text')}" aria-label="${t('查找文字','Find text')}"><span class="find-count">0/0</span><button aria-label="${t('上一个','Previous')}">↑</button><button aria-label="${t('下一个','Next')}">↓</button><button aria-label="${t('关闭','Close')}">×</button>`;$('phone').append(findBar);const buttons=findBar.querySelectorAll('button');buttons[0].onclick=()=>move(-1);buttons[1].onclick=()=>move(1);buttons[2].onclick=closeFind;const input=findBar.querySelector('input');input.value=query;input.oninput=()=>{query=input.value;mark()};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();move(e.shiftKey?-1:1)}if(e.key==='Escape')closeFind()};mark();input.focus()}
  async function share(){const page=current();if(!page)return;try{if(navigator.share)await navigator.share({title:pageTitle(page),url:page.url.startsWith('http')?page.url:location.href});else await copy()}catch(error){if(error.name!=='AbortError')toast(t('分享未完成，请使用浏览器分享菜单。','Use your browser share menu.'))}}
  async function copy(){try{await navigator.clipboard.writeText(current()?.url||location.href);toast(t('链接已复制','Link copied'))}catch{toast(t('无法访问剪贴板，可长按地址复制。','Clipboard unavailable. Select the address to copy it.'))}}
  function downloadBlob(blob,name){const url=URL.createObjectURL(new Blob([blob],{type:'application/octet-stream'})),a=document.createElement('a');a.href=url;a.download=name.replace(/[\\/:\0\n\r]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
  function pageMenu(){const page=current();if(!page)return;tab='tools';$('sheet').hidden=false;$('app').inert=true;renderSheet()}
  function menuHTML(){const page=current();let domain='zero red';try{domain=new URL(page.url).hostname}catch{}return `<div class="sheet-handle"></div><div class="sheet-head"><strong>${esc(domain)}</strong><button data-action="closeSheet">${t('完成','Done')}</button></div><div class="sheet-content"><div class="page-action-grid"><button data-action="sharePage">${icon('external')}<span>${t('分享','Share')}</span></button><button data-action="copyPage">${icon('bookmark')}<span>${t('复制链接','Copy link')}</span></button><button data-action="findPage">${icon('search')}<span>${t('页内查找','Find in page')}</span></button><button data-action="readCurrent">${icon('reading')}<span>${t('阅读模式','Reader')}</span></button><button data-action="savePageFile">${icon('download')}<span>${t('下载文件','Download file')}</span></button><button data-action="reload">${icon('refresh')}<span>${t('刷新','Reload')}</span></button></div><p class="small-note">${page.url.startsWith('https:')?t('此地址使用 HTTPS；连接加密不代表内容一定可信。','This URL uses HTTPS. Encryption does not guarantee trustworthy content.'):t('此页面为内置示例或未加密地址。','This is a built-in demo or an unencrypted URL.')}</p><p class="small-note">${t('网页预览无法控制外部网站的 Cookie、相机、定位或浏览器安全策略。原生版提供网站权限及内容拦截设置。','The web preview cannot control external website cookies, camera, location or browser security. The native app has site permissions and content-blocking settings.')}</p></div>`}
  function init(){document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='f'&&(current()||ZeroReader.isOpen())){e.preventDefault();find()}if(e.key==='Escape'&&findBar){e.stopImmediatePropagation();closeFind()}},true)}
  return{init,find,closeFind,share,copy,downloadBlob,pageMenu,menuHTML};
})();
